// OneKey patch: store inversify DI metadata in a module-local WeakMap instead of
// the global Reflect intrinsic, so the Ledger DMK works under SES lockdown
// (which freezes Reflect). Mirrors reflect-metadata for the (target, key)
// class-level metadata these helpers use. Verified by sesHardenLibCompat.test.ts.
const okStore=new WeakMap();
function okSet(target,key,val){let m=okStore.get(target);if(m===undefined){m=new Map();okStore.set(target,m)}m.set(key,val)}
