function t(t,e){return okGetOwn(t,e)}function e(t,e){return okGet(t,e)}function n(t,e,n){okSet(t,e,n)}function a(e,n,a,f){const c=f(t(e,n)??a());okSet(e,n,c)}function f(t,n,a,f){const c=f(e(t,n)??a());okSet(t,n,c)}export{t as getOwnReflectMetadata,e as getReflectMetadata,n as setReflectMetadata,a as updateOwnReflectMetadata,f as updateReflectMetadata};
